26	Trigger hybrid_trigger(const Cli& cli, const std::string& elf,
27	                       std::string& err) {
28	  err.clear();
29	  // --trigger is REQUIRED for hybrid: no silent default. An absent trigger used
30	  // to fall back to marker, which masked running an unmarked ELF (the fast leg
31	  // ran to completion instead of draining at the ROI, surfacing only as a
32	  // cryptic "expected exit 200, got 0"). Make the user name the ROI delimiter.
33	  if (cli.trigger.empty()) {
34	    err = "--trigger marker|pc is required "
35	          "(the ROI delimiter; see 'andesim run --help')";
36	    return {};
37	  }
38	  const std::string kind = cli.trigger;
39	
40	  if (kind == "marker") return {"marker", {}};  // markers in the workload; no params
41	
42	  if (kind == "pc") {
43	    if (cli.pc_start.empty() || cli.pc_end.empty()) {
44	      err = "trigger pc requires --pc-start and --pc-end "
45	            "(a symbol name or 0x address)";
46	      return {};
47	    }
48	    std::string e1, e2;
49	    const std::string enter = resolve_pc(elf, cli.pc_start, e1);
50	    if (!e1.empty()) { err = e1; return {}; }
51	    const std::string exit = resolve_pc(elf, cli.pc_end, e2);
52	    if (!e2.empty()) { err = e2; return {}; }
53	    // A zero-length ROI (enter == exit) is degenerate: vsim resumes at the
54	    // enter PC and the exit trigger fires on that very instruction, so the
55	    // window measures nothing. Compare numerically -- a symbol and its literal
56	    // 0x address (or 0x0001000 vs 0x1000) are different strings, same PC.
57	    uint64_t a_enter = 0, a_exit = 0;
58	    if (hex_pc(enter, a_enter) && hex_pc(exit, a_exit) && a_enter == a_exit) {
59	      err = "trigger pc: --pc-start and --pc-end resolve to the same address "
60	            "0x" + enter + " (an empty ROI measures nothing)";
61	      return {};
62	    }
63	    // Store with the 0x prefix the plugin (enter_pc=0x..) and vsim
64	    // (--hybrid-exit-pc 0x..) expect; leg_trigger_args concatenates verbatim.
65	    return {"pc", {{"enter_pc", "0x" + enter}, {"exit_pc", "0x" + exit}}};
66	  }
67	
68	  err = "unknown trigger '" + kind + "' (want marker|pc)";
69	  return {};
70	}
